def generate(seed):
    r = random.Random(seed)
    while True:
        R = r.choice([3, 3, 3, 4, 4])
        g = [r.randint(2, 6 if R < 4 else 5) for _ in range(R)]
        if len(set(g)) > 1 and 8 <= sum(g) <= (12 if R < 4 else 11):
            break
    while True:
        a = [r.choice([2, 3, 3, 4]) for _ in range(R - 1)]
        d = [r.randrange(x) for x in a]
        if (sum(d) > 1 and max(x - y for x, y in zip(a, d)) < 3
                and all(a[i] + (a[i - 1] - d[i - 1] if i else 0) < 6
                        for i in range(R - 1))):
            break
    return "/".join(str(g[i]) + (str(a[i]) + str(d[i]) if i < R - 1 else "")
                    for i in range(R))

