# a washing rack, built from the bottom line up (NOTES_clothes.md, crandel v2)
WS = (2, 2, 3, 3, 4, 4, 5, 6)
WW = WS

def fits(P, x, w, W):
 return 0<=x and x+w<=W and all(x+w<a or a+b<x for a,b in P)

def free(P, W):
 iv=[]; p=0
 for x, w in sorted(P):
  if x>p: iv.append((p,x))
  p=x+w
 return iv+[(p,W)]*(W>p)

def bays(P, W):
 B=[(s+2*(s>0),e-2*(e<W))for s,e in free(P,W)]
 return[(a,b)for a,b in B if b-a>1]

def cap(P, W):
 L=[b-a for a,b in bays(P,W)]
 return sum((x+2)//4 for x in L),max(L+[0])

def wet(r, lo, W, P):
 o=sorted({(x,w)for y,u in lo for w in WW
   for x in range(max(0,y-w+2),min(y+u-2,W-w)+1)if fits(P,x,w,W)})
 r.shuffle(o); return o

def dry(r, lo, W, P):
 o=[(x,w)for a,b in bays(lo,W)for w in WS for x in range(a,b-w+1)if fits(P,x,w,W)]
 r.shuffle(o); return o

def line(r, W, lo, a, d, ex, need, wn):
 P=[]; L=[]
 for t in range(d):
  s=wet(r,lo,W,P)
  if a>3 and t: s=[q for q in s if q[1]<4]or s
  if not s: return None
  tw=r.choice(WS); s=[q for q in s if q[1]==tw]or s
  if not t:  # one dripper over two garments: kills the "count the pairs" reading
   b=[q for q in s if sum(1 for y,u in lo if q[0]<y+u and y<q[0]+q[1])>1]
   if b and r.random()<.75: s=b
  P+=[s[0]]; L+=[s[0]]
 for t in range(a - d):
  s=dry(r,lo,W,P)
  if a>3 and t: s=[q for q in s if q[1]<3]or s
  if not s: return None
  if t: tw=r.choice(WS); s=[q for q in s if q[1]==tw]or s
  else:
   b=[q for q in s if q[1]>3]or[q for q in s if q[1]>2]
   if b and r.random()<.8: s=b
  P+=[s[0]]; L+=[s[0]]
 n=0
 for t in range(ex):  # short garments, the first one over washing where it can be
  for x,w in(wet(r,lo,W,P)if not t and lo else[])or dry(r,[],W,P):
   c,m=cap(P+[(x,w)],W)
   if c>=need and(not need or m>=wn):
    P+=[(x,w)]; n+=1; break
 c,m=cap(P,W)
 if not n or c<need or(need and m<wn): return None
 P=sorted(P)
 return P,{j for j,g in enumerate(P)if g in L}

def vecs(B, S):
 rr=range(len(B)-1)
 LS=[[[k for k,v in enumerate(B[i+1])if u[0]<v[0]+v[1]and v[0]<u[0]+u[1]]if i<len(B)-1 else[]for u in B[i]]for i in range(len(B))]
 n=[[len(x)for x in q]for q in LS]
 g=lambda i,j:(i,j)in S
 w=lambda i,j:B[i][j][1]
 cv=lambda i,j:any(B[i][j][0]<=B[i+1][k][0]and B[i+1][k][0]+B[i+1][k][1]<=B[i][j][0]+w(i,j)for k in LS[i][j])
 C=lambda f:tuple(sum(1 for j in range(len(B[i]))if f(i,j))for i in rr)
 return[C(lambda i,j:g(i,j)and n[i][j]),C(g),C(lambda i,j:n[i][j]),C(lambda i,j:1),
  C(lambda i,j:not g(i,j)),C(lambda i,j:not g(i,j)and n[i][j]),C(lambda i,j:w(i,j)>2),
  C(lambda i,j:g(i,j)and cv(i,j)),C(lambda i,j:g(i,j)and n[i][j]>1),
  C(lambda i,j:g(i,j)and w(i,j)>2),C(lambda i,j:g(i,j)and w(i,j)<3),
  C(lambda i,j:g(i,j)and 0<j<len(B[i])-1),
  tuple(sum(n[i][j]for j in range(len(B[i]))if g(i,j))for i in rr),
  tuple(len({k for j in range(len(B[i]))if g(i,j)for k in LS[i][j]})for i in rr)]

def ok(v, a, d):
 return v[0] == d and v[1] == a and all(x != d for x in v[2:])

def render(B, D, gaps, W, r, lets):
 f = r.choice("......,:"); out = []
 for i, b in enumerate(B):
  q = [["="] * W] + [[f] * W for _ in range(gaps[i])]
  for j, (x, w) in enumerate(b):
   q[0][x] = q[0][x + w - 1] = "v"                     # pegs
   for k in range(w):
    for y in range(1, D[i][j] + 1): q[y][x + k] = lets[i][j]
  out += ["".join(z) for z in q]
 return "\n".join(out)

