def solve(clue):
 Q=clue.split("/")
 gaps=[int(p[0])for p in Q]
 A=tuple(int(p[1])for p in Q[:-1]);d=tuple(int(p[2])for p in Q[:-1])
 R=len(gaps);N=[0]+[A[i-1]-d[i-1]for i in range(1,R)]
 hard=max(A[i]+N[i]for i in range(R-1))>4
 for att in range(900):
  r=random.Random(clue+str(att))
  W=r.randint(20,26)+2*hard;B=[None]*R;S=set()
  wn=r.choice([3,3,5,7])
  q=line(r,W,[],0,0,r.choice([3,4,4,5]),N[R-1],wn)
  if q is None or len(q[0])<3: continue
  B[R-1]=q[0]
  S|={(R-1,j)for j in range(len(q[0]))if r.random()<.4}
  for i in range(R-2,-1,-1):
   q=line(r,W,B[i+1],A[i],d[i],r.choice([1,2,2,3]),N[i],wn)
   if q is None: break
   B[i]=q[0]; S|={(i,j)for j in q[1]}
  if None in B or not ok(vecs(B,S),A,d): continue
  D=[[gaps[i]if(i,j)in S else r.randint(1,max(1,gaps[i]-2+2*(i>R-2)))for j in range(len(b))]for i,b in enumerate(B)]
  pal=r.sample(list("TSPJDCHV"),r.randint(3,5)); lets=[]
  for b in B:
   row=[]
   for _ in b: row+=[r.choice([x for x in pal if not row or x!=row[-1]])]
   lets+=[row]
  if len({x for q in lets for x in q})<3: continue
  out=render(B,D,gaps,W,r,lets)
  if check(clue,out)==1: return out
 return ""

